import React from 'react';
import { Link } from 'react-router-dom';

// --- STYLES ---
// Kept as a JS object for consistency, but these could easily be moved to a CSS file.
const styles = {
  footer: {
    backgroundColor: '#1a202c',
    color: '#a0aec0',
    padding: '30px 20px',
    textAlign: 'center',
    borderTop: '1px solid #2d3748',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  nav: {
    marginBottom: '20px',
  },
  copyright: {
    marginTop: '16px',
    fontSize: '0.9rem',
    color: '#a0aec0',
  }
};

// --- CSS FOR DYNAMIC STYLES ---
// A <style> tag is used here for a self-contained example.
// In a real application, this would go into a separate CSS/SCSS file or a CSS-in-JS library.
const dynamicStyles = `
  .footer-link {
    color: #e2e8f0;
    text-decoration: none;
    margin: 0 15px;
    font-size: 1rem;
    transition: color 0.3s ease;
  }

  .footer-link:hover {
    color: #a7ffeb; /* The highlight color is now handled by CSS */
  }
`;

const Footer = () => {
  // Array of footer links remains the same
  const footerLinks = [
    { text: 'Home', path: '/', isRouterLink: true },
    { text: 'About Us', path: '/about', isRouterLink: true },
    { text: 'Services', path: '/#services', isRouterLink: false },
    { text: 'Contact Us', path: '/#contact', isRouterLink: false },
    { text: 'Terms and Conditions', path: '/terms', isRouterLink: true },
  ];

  return (
    <>
      {/* Inject the dynamic styles into the document head */}
      <style>{dynamicStyles}</style>
      
      <footer style={styles.footer}>
        <div style={styles.container}>
          {/* Added aria-label for better accessibility */}
          <nav style={styles.nav} aria-label="Footer navigation">
            {footerLinks.map(({ text, path, isRouterLink }) => 
              isRouterLink ? (
                <Link
                  key={text}
                  to={path}
                  className="footer-link" // Use className instead of inline style
                >
                  {text}
                </Link>
              ) : (
                <a
                  key={text}
                  href={path}
                  className="footer-link" // Use className instead of inline style
                >
                  {text}
                </a>
              )
            )}
          </nav>
          <p style={styles.copyright}>
            &copy; {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
          </p>
        </div>
      </footer>
    </>
  );
};

export default Footer;
